          variant="outline"
          aria-label={t("workspace.settings.api_keys.rotate_key")}
          onClick={(event) => {
            event.stopPropagation();
            onRotate(apiKey);
          }}
          data-testid="rotate-key-button">
          <RotateCwIcon className="size-3.5" />
          <span className="sr-only sm:not-sr-only sm:inline">{t("workspace.settings.api_keys.rotate_key")}</span>
        </Button>
        <Button
          size="icon"
          variant="ghost"
          aria-label={t("common.delete")}
          onClick={(event) => onDelete(event, apiKey)}>
