/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate — rotate an API key.
 *
 * Generates a new secret, updates the stored hashes, and returns the new plaintext key
 * (which the caller must show once). Thin adapter over the service layer.
 */
import { ZId } from "@formbricks/types/common";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { assertCan } from "@/lib/authorization";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { TApiKeyWithEnvironmentPermission } from "@/modules/organization/settings/api-keys/types/api-keys";
import { successResponse } from "@/app/api/v3/lib/response";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZId },
  handler: async ({ parsedInput, authentication, auditLog, requestId }) => {
    const apiKeyId = parsedInput.params.id;

    const organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
    await assertCan({ type: "user", id: authentication.userId! }, "apiKey.manage", {
      type: "apiKey",
      id: apiKeyId,
    });

    const result = await rotateApiKey(apiKeyId, authentication.userId!);

    // Carry the organization into the audit log so the event is attributable to the org.
    auditLog.organizationId = organizationId;
    auditLog.objectId = apiKeyId;
    auditLog.newObject = { id: result.id };

    return successResponse(result as TApiKeyWithEnvironmentPermission & { actualKey: string }, {
      requestId,
    });
  },
});

/**
 * Client-side API functions for the API keys v3 routes.
 *
 * These are the network calls that TanStack Query hooks in this module use.
 * Every function throws a parsed `V3ApiError` on a non-2xx response.
 */
import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import type { TApiKeyWithEnvironmentPermission } from "../types/api-keys";

const JSON_HEADERS = { "Content-Type": "application/json" };

/** Timeout for mutations so a stalled request does not leave spinners stuck indefinitely. */
const MUTATION_TIMEOUT_MS = 15_000;

export type TRotateApiKeyResponse = TApiKeyWithEnvironmentPermission & { actualKey: string };

export async function rotateApiKey(apiKeyId: string): Promise<TRotateApiKeyResponse> {
  const response = await fetch(`/api/v3/api-keys/${apiKeyId}/rotate`, {
    method: "POST",
    cache: "no-store",
    signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const body = (await response.json()) as { data: TRotateApiKeyResponse };
  return body.data;
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { rotateApiKey } from "../lib/api-client";
import type { TApiKeyWithEnvironmentPermission } from "../types/api-keys";

/** Key factory for API keys query cache. */
export const apiKeyKeys = {
  all: () => ["apiKeys"] as const,
  lists: () => [...apiKeyKeys.all(), "list"] as const,
  list: (organizationId: string) => [...apiKeyKeys.lists(), organizationId] as const,
  details: () => [...apiKeyKeys.all(), "detail"] as const,
  detail: (apiKeyId: string) => [...apiKeyKeys.details(), apiKeyId] as const,
};

export const useRotateApiKey = (organizationId: string) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ apiKeyId }: { apiKeyId: string }) => rotateApiKey(apiKeyId),
    onMutate: async ({ apiKeyId }) => {
      await queryClient.cancelQueries({ queryKey: apiKeyKeys.list(organizationId) });
      const previousData = queryClient.getQueryData<TApiKeyWithEnvironmentPermission[]>(
        apiKeyKeys.list(organizationId)
      );
      // Optimistically remove the key from the list (the old key is invalidated immediately).
      queryClient.setQueryData<TApiKeyWithEnvironmentPermission[]>(apiKeyKeys.list(organizationId), (current) =>
        current?.filter((key) => key.id !== apiKeyId)
      );
      return { previousData };
    },
    onError: (_error, _variables, context) => {
      if (context?.previousData) {
        queryClient.setQueryData(apiKeyKeys.list(organizationId), context.previousData);
      }
    },
    onSettled: () => {
      void queryClient.invalidateQueries({ queryKey: apiKeyKeys.list(organizationId) });
    },
  });
};

